      int lo = (grp == 0x08) ? 0 : 3, hi = (grp == 0x08) ? 3 : 0x0B, y = 0;
      for (int i = lo; i < hi; i++) if (s[0xAEFF + i] != 0xFF) s[0xAD8E + y++] = (uint8_t)i;
      if (!y) fail = 1; else { n = y; v3A = 1; }
