              s[0xA2F6 + y] = 1; s[0xA878 + y] = 0; s[0xA31C + y] = 0; s[0xA1E0 + y] = 0;   // C1/72D3-72DF
              s[0xA368 + y] = s[0xA240 + x2]; s[0xA37B + y] = s[0xA250 + x2];   // C1/72E5-72EE
              wr16(s, 0xA89E + x2, rd16(s, 0xA880)); wr16(s, 0xA8C4 + x2, rd16(s, 0xA882));   // C1/72F3-72FC
              wr16(s, 0xA8EA + x2, 0); wr16(s, 0xA910 + x2, 0);              // C1/72FF-7303
              battleLaw7313(s, s[0xA32F + x2]);                             // C1/7308-730B (`LDA $A32F,X`, X = slot * 2)
              if (tr) fprintf(stderr, "asc f%d rel=%d t%d SLIDE-MID to=(%d,%d) n=%d step=%04X/%04X AAFC=%d AAFE=%d\n",
                              h->frames, rel, t, gx, gy, s[0xABF6 + y], rd16(s, 0xA89E + x2), rd16(s, 0xA8C4 + x2), rd16(s, 0xAAFC), rd16(s, 0xAAFE));
