            s[0xA2B0] = (uint8_t)gx; s[0xA2B2] = (uint8_t)gy;
            int lx, ly; battleAscGetPos(h, t, &lx, &ly); lx &= 0xFF; ly &= 0xFF;
            unsigned ux, uy; battleLaw65BA(s, lx, ly, gx & 0xFF, gy & 0xFF, &ux, &uy);   // C1/7468
