    // (s1400 f346: `$CCB0 = 00 (D1:F200)`, `$CCB8 (D1:F209)`, `$CCC0 (D1:F20C)`, `$CCE5 (D1:F224)`): $CA16 $CA23 $CD23
    // $CCB0 $CD29 $CD2D $CCB8 $CCC0, $CCA4..$CCAF, $CD2E $CCE5, $CD07, $99D2/3, $CD0A/B, $BB01..$BB04, $CD0C $CE11,
    // $CAD3, $7C/$7D (the NMI counter CD/0AEE and the window buffers' parity count from HERE), $CD44/5, $CDC7/8,
    // $CD3C $CD43. (The HUD band's and the NMI's own bytes of the run -- $7E $7F $CA25 $CD27 $CE0A..$CE19 -- are not
    // taken: the port's band keeps its own staging.)
    m[0xCA16] = 0; m[0xCA23] = 0; m[0xCD23] = 0; m[0xCCB0] = 0; m[0xCD29] = 0; m[0xCD2D] = 0; m[0xCCB8] = 0; m[0xCCC0] = 0;
