                                                                   // ($CA92, D1/F250: CD/06B4's variant -- a seed's leftover picked another fill)
    m[0xCD44] = m[0xCD45] = 0; m[0xCDC7] = m[0xCDC8] = 0; m[0xCD3C] = 0; m[0xCD43] = 0;
