    if (v[0] >= v[2]) TSW(0, 1);                                   // CD/36B5-36C1
    int s03 = battleFxTriSlope(v[4], v[0], v[5] - v[1], &g0);      // CD/3777-3789
    int s05 = battleFxTriSlope(v[4], v[2], v[5] - v[3], &g1);      // CD/378B-379D
    n0 = (v[5] - v[1]) & 0xFF; n1 = 0;                             // $0F = y0, $11 = $10 = y2
    sa[0] = s03; sb[0] = s05; sa[1] = sb[1] = 0;
